\set ON_ERROR_STOP on
BEGIN;
DO $vedu_patch$
DECLARE
  spec jsonb;
  pack jsonb;
  v_cid int;
  v_ord int;
  v_lesson bigint;
  v_quiz bigint;
  v_count int;
  v_question bigint;
  v_old_question bigint;
  v_answer bigint;
  v_k int;
  v_j int;
  v_url text;
  v_pdf jsonb;
  v_attempts bigint;
BEGIN
  FOR spec IN SELECT value FROM jsonb_array_elements($QUIZ_JSON$[{"course":63,"order":2,"questions":[{"text":"Nếu đồ thị vô hướng có bốn đỉnh bậc 1,2,2,3 thì tổng số cạnh là bao nhiêu?","options":["8","3","6","4"],"correct":3},{"text":"Trong đồ thị vô hướng, mỗi cạnh nối hai đỉnh đóng góp bao nhiêu vào tổng bậc?","options":["2","1","0","4"],"correct":0},{"text":"Đồ thị có hướng biểu diễn liên kết A đến B theo cách nào?","options":["Hai đồ thị không liên quan","Một cung A→B","Cạnh bắt buộc hai chiều","Một đỉnh mới C"],"correct":1},{"text":"Trong đồ thị vô hướng, tổng bậc các đỉnh bằng gì?","options":["Hai lần số cạnh","Số cạnh","Số đỉnh","Bình phương số cạnh"],"correct":0},{"text":"Đồ thị đơn không cho phép điều nào?","options":["Đường đi","Cạnh song song và khuyên","Đỉnh cô lập","Cạnh vô hướng"],"correct":1},{"text":"Đồ thị có hướng khác đồ thị vô hướng ở điểm nào?","options":["Không có chu trình","Mọi đỉnh đều bậc 2","Cạnh có chiều xác định","Không có đỉnh"],"correct":2},{"text":"Bậc của đỉnh trong đồ thị vô hướng là gì?","options":["Số đỉnh của đồ thị","Số đường đi bất kỳ","Số thành phần liên thông","Số cạnh kề với đỉnh đó"],"correct":3},{"text":"Một đồ thị đơn vô hướng có 4 đỉnh thì số cạnh tối đa bằng bao nhiêu?","options":["6","4","8","12"],"correct":0},{"text":"Đỉnh cô lập trong đồ thị vô hướng có bậc bằng bao nhiêu?","options":["Số đỉnh của đồ thị","0","1","2"],"correct":1},{"text":"Đồ thị có 6 cạnh thì tổng bậc các đỉnh là bao nhiêu?","options":["18","36","12","6"],"correct":2}]},{"course":63,"order":3,"questions":[{"text":"Danh sách kề của A:[B,C] cho biết điều gì?","options":["Đồ thị có đúng hai đỉnh","A kề với B và C","A chỉ nối với chính nó","B không kề A trong đồ thị vô hướng"],"correct":1},{"text":"Một ma trận kề 5×5 biểu diễn đồ thị có bao nhiêu đỉnh?","options":["25","4","5","10"],"correct":2},{"text":"Trong đồ thị có hướng, ma trận kề có bắt buộc đối xứng không?","options":["Có trong mọi trường hợp","Chỉ khi có 5 đỉnh","Chỉ khi có khuyên","Không"],"correct":3},{"text":"Ma trận kề của đồ thị đơn vô hướng có tính chất gì?","options":["Mọi phần tử bằng 1","Luôn có đường chéo bằng 1","Đối xứng qua đường chéo chính","Luôn tam giác trên"],"correct":2},{"text":"Danh sách kề lưu thông tin gì?","options":["Toàn bộ đường đi Hamilton","Duy nhất trọng số nhỏ nhất","Chỉ tên đồ thị","Các đỉnh kề của từng đỉnh"],"correct":3},{"text":"Đồ thị thưa nên ưu tiên biểu diễn nào để tiết kiệm bộ nhớ?","options":["Danh sách kề","Ma trận kề đầy đủ","Bảng n nhân n toàn số 0","Mảng lưu mọi hoán vị"],"correct":0},{"text":"Ma trận kề của đồ thị n đỉnh có kích thước nào?","options":["2 nhân n","n nhân n","n nhân m","m nhân m nhân n"],"correct":1},{"text":"Với đồ thị đơn không khuyên, đường chéo ma trận kề bằng gì?","options":["Toàn số âm","Bằng số cạnh","Toàn số 0","Toàn số 1"],"correct":2},{"text":"Trong đồ thị vô hướng, cạnh AB xuất hiện như thế nào trong danh sách kề?","options":["Chỉ A có B","Chỉ B có A","Không ở danh sách nào","B trong danh sách A và A trong danh sách B"],"correct":3},{"text":"Thêm một cạnh vào đồ thị biểu diễn bằng ma trận kề cần cập nhật bao nhiêu ô với cạnh vô hướng AB khác nhau?","options":["2","0","1","n nhân n"],"correct":0}]},{"course":63,"order":4,"questions":[{"text":"Một đồ thị có 4 đỉnh A,B,C,D; BFS từ A có thể thăm D trước B nếu B kề trực tiếp A còn D cách hai cạnh không?","options":["Có bắt buộc","Có vì D có tên dài hơn","Có trong mọi đồ thị","Không"],"correct":3},{"text":"Thứ tự duyệt DFS có thể phụ thuộc vào yếu tố nào?","options":["Thứ tự xét các đỉnh kề","Chỉ số lượng đỉnh","Màu giao diện","Định dạng PDF"],"correct":0},{"text":"Nếu đồ thị không liên thông, duyệt BFS từ một đỉnh sẽ thăm gì?","options":["Không thăm đỉnh nào","Chỉ thành phần liên thông chứa đỉnh nguồn","Tất cả đỉnh trong mọi thành phần","Chỉ các đỉnh bậc 0"],"correct":1},{"text":"BFS sử dụng cấu trúc dữ liệu nào?","options":["Hàng đợi","Ngăn xếp","Cây tìm kiếm nhị phân","Đống tối đa"],"correct":0},{"text":"DFS thường được cài đặt bằng cấu trúc nào?","options":["Ma trận nghịch đảo","Ngăn xếp hoặc đệ quy","Hàng đợi ưu tiên bắt buộc","Bảng băm duy nhất"],"correct":1},{"text":"Trên đồ thị không trọng số, BFS tìm được điều gì?","options":["Chu trình Hamilton tối ưu","Cây khung nhỏ nhất có trọng số","Đường đi có ít cạnh nhất từ nguồn","Đường đi có tổng trọng số âm nhỏ nhất"],"correct":2},{"text":"Khi BFS, các đỉnh được thăm theo nguyên tắc nào?","options":["Theo trọng số cạnh giảm dần","Theo bậc đỉnh lớn nhất","Theo thứ tự ngẫu nhiên bắt buộc","Theo từng lớp khoảng cách từ nguồn"],"correct":3},{"text":"Để tránh lặp vô hạn khi duyệt đồ thị có chu trình, cần dùng gì?","options":["Tập đỉnh đã thăm","Bộ đếm cạnh âm","Ma trận định thức","Bảng chân trị"],"correct":0},{"text":"Nếu A nối B và C, B nối D thì khoảng cách ít cạnh nhất từ A đến D là bao nhiêu?","options":["4","2","1","3"],"correct":1},{"text":"BFS trên đồ thị biểu diễn danh sách kề có độ phức tạp thường là gì?","options":["O(1) với mọi đồ thị","O(E bình phương V)","O(V+E)","O(V!)"],"correct":2}]},{"course":63,"order":5,"questions":[{"text":"Trong đồ thị vô hướng, số đỉnh bậc lẻ luôn là số như thế nào?","options":["Bằng 1","Số chẵn","Số lẻ","Bằng số cạnh"],"correct":1},{"text":"Đường đi Euler khác chu trình Euler ở điểm nào?","options":["Chu trình Euler không xét cạnh","Hai khái niệm luôn giống nhau","Đường đi Euler không bắt buộc trở về đỉnh xuất phát","Đường đi Euler phải đi qua mọi đỉnh đúng một lần"],"correct":2},{"text":"Đồ thị DAG là viết tắt của gì?","options":["Đồ thị vô hướng đầy đủ","Đồ thị chỉ có cạnh âm","Đồ thị có đúng một đỉnh","Đồ thị có hướng không chu trình"],"correct":3},{"text":"Đường đi Euler được định nghĩa là gì?","options":["Đi qua cạnh có trọng số nhỏ nhất","Đi qua tất cả cạnh ít nhất hai lần","Đi qua mỗi cạnh đúng một lần","Đi qua mỗi đỉnh đúng một lần"],"correct":2},{"text":"Đường đi Hamilton được định nghĩa là gì?","options":["Đi qua mỗi cạnh đúng một lần","Luôn đi qua đỉnh xuất phát hai lần","Chỉ áp dụng cho cây","Đi qua mỗi đỉnh đúng một lần"],"correct":3},{"text":"Đồ thị vô hướng liên thông có chu trình Euler khi nào?","options":["Mọi đỉnh có bậc chẵn","Mọi đỉnh có bậc lẻ","Có đúng một đỉnh bậc lẻ","Có chu trình độ dài 3"],"correct":0},{"text":"Đồ thị vô hướng liên thông có đường đi Euler mở khi nào?","options":["Không có cạnh","Có đúng hai đỉnh bậc lẻ","Có đúng ba đỉnh bậc lẻ","Mọi đỉnh có bậc lẻ"],"correct":1},{"text":"Sắp xếp topo áp dụng cho loại đồ thị nào?","options":["Mọi đồ thị có chu trình","Chỉ đồ thị đầy đủ","Đồ thị có hướng không chu trình","Mọi đồ thị vô hướng"],"correct":2},{"text":"Nếu đồ thị có hướng chứa chu trình thì có thể có thứ tự topo hợp lệ không?","options":["Có trong mọi trường hợp","Có nếu chu trình dài 3","Có nếu bỏ qua hướng cạnh","Không"],"correct":3},{"text":"Trong một thứ tự topo, cạnh u đến v yêu cầu điều gì?","options":["u đứng trước v","v luôn đứng trước u","u và v cùng vị trí","Không có ràng buộc"],"correct":0}]},{"course":63,"order":6,"questions":[{"text":"Với A→B=4, A→C=10 và B→C=2, khoảng cách ngắn nhất từ A đến C là bao nhiêu?","options":["10","4","12","6"],"correct":3},{"text":"Dijkstra thường khởi tạo khoảng cách các đỉnh khác nguồn bằng giá trị nào?","options":["Vô cực","0","1","-1"],"correct":0},{"text":"Vì sao không nên áp dụng Dijkstra trực tiếp khi có cạnh âm?","options":["Vì cạnh âm bị cấm trong toán học","Chọn đỉnh tối ưu tạm thời có thể không còn đúng","Vì mọi cạnh âm tạo chu trình","Vì đồ thị không có đỉnh"],"correct":1},{"text":"Dijkstra bảo đảm đúng với điều kiện nào?","options":["Không có cạnh trọng số âm","Mọi cạnh có trọng số âm","Đồ thị phải là cây","Đồ thị không được có chu trình"],"correct":0},{"text":"Khoảng cách từ đỉnh nguồn đến chính nó ban đầu là bao nhiêu?","options":["-1","0","1","Vô cực"],"correct":1},{"text":"Bellman-Ford khác Dijkstra ở khả năng nào?","options":["Không dùng trọng số","Luôn chạy O(1)","Xử lý cạnh trọng số âm và phát hiện chu trình âm có thể đạt","Chỉ duyệt đồ thị vô hướng"],"correct":2},{"text":"Phép nới lỏng cạnh u đến v có trọng số w cập nhật điều gì?","options":["d[v] bằng d[u]-w bất kể điều kiện","d[u] luôn bằng vô cực","Xóa cạnh u đến v","d[v] bằng min của d[v] và d[u]+w"],"correct":3},{"text":"A đến B trọng số 2 và B đến C trọng số 3 thì đường A-B-C dài bao nhiêu?","options":["5","1","6","23"],"correct":0},{"text":"Dijkstra chọn đỉnh tiếp theo theo tiêu chí nào?","options":["Trọng số cạnh lớn nhất","Khoảng cách tạm thời nhỏ nhất","Bậc đỉnh lớn nhất","Tên đỉnh dài nhất"],"correct":1},{"text":"Chu trình âm có thể khiến điều gì xảy ra với bài toán đường đi ngắn nhất?","options":["Mọi đỉnh không liên thông","Thuật toán BFS tính được trọng số đúng","Không tồn tại khoảng cách hữu hạn tối ưu nếu chu trình âm đến được và dẫn tới đích","Luôn có đường đi độ dài 0"],"correct":2}]},{"course":63,"order":7,"questions":[{"text":"Kruskal với cạnh AB=2, BC=3, AC=10 chọn hai cạnh nào cho cây khung nhỏ nhất?","options":["Chỉ AC","AB và BC","AB và AC","BC và AC"],"correct":1},{"text":"Một cây khung có 6 đỉnh phải có bao nhiêu cạnh?","options":["7","10","5","6"],"correct":2},{"text":"Đồ thị vô hướng liên thông có tất cả trọng số cạnh phân biệt thì MST có duy nhất không?","options":["Không bao giờ","Chỉ khi đồ thị là chu trình","Chỉ khi không có cạnh","Có"],"correct":3},{"text":"Cây khung của đồ thị liên thông n đỉnh chứa bao nhiêu cạnh?","options":["n+1","2n","n-1","n"],"correct":2},{"text":"Mục tiêu cây khung nhỏ nhất là gì?","options":["Tối đa số cạnh","Tối đa tổng bậc đỉnh","Tìm đường Hamilton","Tối thiểu tổng trọng số cạnh"],"correct":3},{"text":"Kruskal chọn cạnh theo thứ tự nào?","options":["Trọng số tăng dần nếu không tạo chu trình","Trọng số giảm dần không xét chu trình","Theo tên đỉnh","Theo số lượng đỉnh lẻ"],"correct":0},{"text":"Prim xây dựng cây khung bằng cách nào?","options":["Đảo hướng mọi cạnh","Mở rộng từ tập đỉnh đã chọn bằng cạnh nhẹ nhất bắc ra ngoài","Duyệt từng lớp bằng BFS","Xóa mọi cạnh nhỏ nhất"],"correct":1},{"text":"Cấu trúc thường dùng để phát hiện chu trình trong Kruskal là gì?","options":["Bảng chân trị","Ma trận chuyển vị","Disjoint Set Union","Ngăn xếp cuộc gọi duy nhất"],"correct":2},{"text":"Đồ thị có trọng số AB=1 BC=2 AC=5 thì tổng trọng số MST bằng bao nhiêu?","options":["8","6","5","3"],"correct":3},{"text":"MST thường được xác định trên loại đồ thị nào?","options":["Đồ thị vô hướng liên thông có trọng số","Đồ thị có hướng bất kỳ","Mọi đồ thị chỉ có cạnh âm","Đồ thị không có cạnh"],"correct":0}]},{"course":63,"order":8,"questions":[{"text":"Nếu p sai, q đúng thì p→q có giá trị gì?","options":["Sai","Không xác định","Bằng p∧q","Đúng"],"correct":3},{"text":"Mệnh đề p∧¬p có giá trị gì?","options":["Luôn sai","Luôn đúng","Bằng p","Bằng ¬p"],"correct":0},{"text":"Định luật De Morgan cho ¬(p∧q) là gì?","options":["p∧q","¬p∨¬q","¬p∧¬q","p∨q"],"correct":1},{"text":"Mệnh đề trong logic là gì?","options":["Câu khẳng định có giá trị đúng hoặc sai xác định","Mọi câu hỏi mở","Mọi biến không gán giá trị","Bất kỳ câu cảm thán"],"correct":0},{"text":"Phủ định của mệnh đề đúng có giá trị gì?","options":["Bằng số 1","Sai","Đúng","Không xác định trong logic cổ điển"],"correct":1},{"text":"Phép hội p và q đúng khi nào?","options":["Chỉ q đúng","Cả p và q đều sai","Cả p và q đều đúng","Chỉ p đúng"],"correct":2},{"text":"Phép tuyển p hoặc q đúng khi nào?","options":["Cả hai phải sai","Chỉ khi cả hai sai","Không phụ thuộc giá trị của p và q","Ít nhất một trong hai mệnh đề đúng"],"correct":3},{"text":"Kéo theo p suy ra q sai khi nào?","options":["p đúng và q sai","p sai và q đúng","Cả hai đúng","Cả hai sai"],"correct":0},{"text":"Phép tương đương p khi và chỉ khi q đúng khi nào?","options":["Chỉ khi p đúng q sai","p và q có cùng giá trị chân trị","p luôn đúng","q luôn sai"],"correct":1},{"text":"Mệnh đề p hoặc phủ định p có giá trị gì?","options":["Chỉ đúng khi p sai","Chỉ đúng khi p đúng","Luôn đúng","Luôn sai"],"correct":2}]},{"course":63,"order":9,"questions":[{"text":"Từ p→q và p, kết luận q dùng quy tắc nào?","options":["Phép đổi chỗ","Modus ponens","Modus tollens","Phép phủ định kép"],"correct":1},{"text":"Nếu p→q và ¬q đúng thì theo modus tollens kết luận gì?","options":["q","p∧q","¬p","p"],"correct":2},{"text":"Từ p∨q và ¬p có thể suy ra q theo quy tắc nào?","options":["Modus ponens","Tổng quát hóa tồn tại","Phép giao tập","Tam đoạn luận tuyển"],"correct":3},{"text":"Quy tắc modus ponens có dạng nào?","options":["Phủ định p suy ra q","p hoặc q suy ra phủ định p","p và p kéo theo q suy ra q","q và p kéo theo q suy ra p"],"correct":2},{"text":"Quy tắc modus tollens có dạng nào?","options":["p kéo theo q và q suy ra p","p suy ra phủ định q","q suy ra p","p kéo theo q và phủ định q suy ra phủ định p"],"correct":3},{"text":"Từ p và q, kết luận hợp lệ nào theo phép hội?","options":["p và q","Phủ định p","Phủ định q","p kéo theo phủ định q"],"correct":0},{"text":"Từ p và q, suy ra kết luận nào bằng phép tách hội?","options":["p sai","p","Phủ định p","Phủ định q"],"correct":1},{"text":"Phản ví dụ có tác dụng gì khi kiểm tra lập luận?","options":["Thay thế định nghĩa suy diễn","Bảo đảm kết luận đúng","Chứng minh lập luận không hợp lệ bằng trường hợp tiền đề đúng kết luận sai","Chứng minh mọi lập luận đúng"],"correct":2},{"text":"Lập luận hợp lệ nghĩa là gì?","options":["Mọi tiền đề đều sai","Kết luận luôn sai","Chỉ có một tiền đề","Không có trường hợp mọi tiền đề đúng mà kết luận sai"],"correct":3},{"text":"Từ p hoặc q và phủ định p, có thể suy ra gì?","options":["q","p","Phủ định q","p và q đều sai"],"correct":0}]},{"course":63,"order":10,"questions":[{"text":"Phủ định của câu “Mọi sinh viên đều học Python” là gì?","options":["Không sinh viên nào học Python","Mọi sinh viên đều không học Python","Có ít nhất một sinh viên học Python","Tồn tại ít nhất một sinh viên không học Python"],"correct":3},{"text":"Với miền A={1,2,3}, mệnh đề ∃x(x>2) có đúng không?","options":["Đúng","Sai","Không xác định","Chỉ đúng nếu có 4"],"correct":0},{"text":"Với miền A={1,2,3}, mệnh đề ∀x(x>0) có đúng không?","options":["Không thể kiểm tra","Đúng","Sai","Chỉ đúng với x=0"],"correct":1},{"text":"Vị từ P(x) trở thành mệnh đề khi nào?","options":["Khi gán giá trị cho x hoặc lượng hóa x trên miền xác định","Khi x chưa có miền","Khi bỏ mọi biến","Khi viết chữ hoa"],"correct":0},{"text":"Lượng từ với mọi ký hiệu như thế nào?","options":["⇒","∀","∃","¬"],"correct":1},{"text":"Lượng từ tồn tại ký hiệu như thế nào?","options":["∧","⇔","∃","∀"],"correct":2},{"text":"Phủ định của mọi x P(x) tương đương gì?","options":["Mọi x đều P(x)","Không tồn tại x P(x)","Tồn tại x P(x)","Tồn tại x sao cho không P(x)"],"correct":3},{"text":"Phủ định của tồn tại x P(x) tương đương gì?","options":["Mọi x đều không P(x)","Tồn tại x P(x)","Mọi x đều P(x)","Có đúng một x P(x)"],"correct":0},{"text":"Miền xác định trong logic vị từ dùng để làm gì?","options":["Xóa lượng từ","Xác định các đối tượng mà biến nhận giá trị","Chỉ xác định màu của biến","Thay thế giá trị chân trị"],"correct":1},{"text":"Mệnh đề tồn tại x P(x) đúng khi nào?","options":["Miền bắt buộc rỗng","P(x) sai với mọi x","Có ít nhất một phần tử trong miền làm P(x) đúng","Mọi phần tử đều làm P(x) sai"],"correct":2}]},{"course":63,"order":11,"questions":[{"text":"Với A={1,2}, B={2,3}, A∩B là tập nào?","options":["{3}","{2}","{1,2,3}","{1}"],"correct":1},{"text":"Với A={1,2}, B={2,3}, A∪B là tập nào?","options":["{1,3}","{1,2}","{1,2,3}","{2}"],"correct":2},{"text":"Ánh xạ f:A→B là toàn ánh khi nào?","options":["Mọi a có cùng ảnh","A rỗng","Mọi a khác nhau có ảnh khác nhau","Mọi b thuộc B đều có ít nhất một a thuộc A sao cho f(a)=b"],"correct":3},{"text":"Tập hợp A là tập con của B nghĩa là gì?","options":["A và B không giao nhau","A rỗng bắt buộc","Mọi phần tử của A đều thuộc B","Mọi phần tử B đều thuộc A"],"correct":2},{"text":"Hợp A và B chứa các phần tử nào?","options":["Chỉ thuộc A và B đồng thời","Không thuộc A và B","Chỉ thuộc A","Thuộc A hoặc thuộc B"],"correct":3},{"text":"Giao A và B gồm các phần tử nào?","options":["Thuộc cả A lẫn B","Chỉ thuộc A","Chỉ thuộc B","Không thuộc tập nào"],"correct":0},{"text":"Hàm đơn ánh có tính chất nào?","options":["Không có miền xác định","Hai đầu vào khác nhau cho hai đầu ra khác nhau","Mọi đầu ra có hai tiền ảnh","Mọi đầu vào có cùng ảnh"],"correct":1},{"text":"Hàm toàn ánh có nghĩa là gì?","options":["Tập đích rỗng bắt buộc","Hàm không có giá trị","Mọi phần tử tập đích có ít nhất một tiền ảnh","Mọi đầu vào khác nhau có ảnh khác nhau"],"correct":2},{"text":"Một song ánh là hàm thế nào?","options":["Chỉ đơn ánh","Chỉ toàn ánh","Không phải ánh xạ","Vừa đơn ánh vừa toàn ánh"],"correct":3},{"text":"Tập A có 3 phần tử thì tập lũy thừa có bao nhiêu phần tử?","options":["8","3","6","9"],"correct":0}]},{"course":63,"order":12,"questions":[{"text":"C(6,1) bằng bao nhiêu?","options":["1","36","120","6"],"correct":3},{"text":"Số hoán vị của 3 người phân biệt trên ba ghế là bao nhiêu?","options":["6","3","9","27"],"correct":0},{"text":"Chọn 2 đồ vật có thứ tự từ 5 đồ vật có bao nhiêu cách?","options":["5","20","10","25"],"correct":1},{"text":"Chọn k phần tử từ n phần tử không xét thứ tự dùng công thức nào?","options":["C(n,k)","n mũ k","n cộng k","n nhân k"],"correct":0},{"text":"Chỉnh hợp chập k của n phần tử có công thức nào?","options":["k!/n!","n!/(n-k)!","n!/k!/(n-k)!","n+k"],"correct":1},{"text":"Hoán vị của n phần tử phân biệt có bao nhiêu cách?","options":["2n","n bình phương","n!","n"],"correct":2},{"text":"Tổ hợp C(5,2) bằng bao nhiêu?","options":["20","5","25","10"],"correct":3},{"text":"Quy tắc nhân áp dụng khi nào?","options":["Các bước lựa chọn nối tiếp độc lập về số cách theo từng bước","Hai lựa chọn loại trừ nhau phải cộng","Chỉ khi có một phần tử","Chỉ khi thứ tự không quan trọng"],"correct":0},{"text":"Quy tắc cộng thường áp dụng cho các trường hợp nào?","options":["Một phép đếm lặp vô hạn","Các trường hợp lựa chọn loại trừ nhau","Các bước thực hiện liên tiếp bắt buộc","Một chuỗi nhân số"],"correct":1},{"text":"Chọn 2 học viên từ 4 học viên khô