ịnh tuyến IP, nguyên tắc longest prefix match là gì?","options":["Chọn tuyến có tên dài nhất","Luôn chọn default route","Luôn chọn tuyến có metric lớn nhất","Chọn tuyến khớp có tiền tố dài nhất"],"correct":3},{"text":"TTL của IPv4 giảm khi nào?","options":["Khi gói đi qua router","Khi gói được lưu vào PDF","Khi mở trình duyệt","Khi nhận email ngoại tuyến"],"correct":0},{"text":"Địa chỉ default gateway của host thường là gì?","options":["Địa chỉ broadcast","Địa chỉ IP giao diện router trong mạng cục bộ","Địa chỉ MAC của bàn phím","Địa chỉ DNS bắt buộc"],"correct":1},{"text":"Giao thức ICMP thường dùng vào mục đích nào?","options":["Nén ảnh PNG","Cấp phát RAM","Thông báo lỗi và chẩn đoán mạng","Lưu cơ sở dữ liệu SQL"],"correct":2},{"text":"Lệnh ping thường dùng giao thức nào để kiểm tra kết nối IPv4?","options":["SMTP","FTP","POP3","ICMP Echo"],"correct":3},{"text":"Khi không có tuyến cụ thể, router có thể dùng gì nếu được cấu hình?","options":["Tuyến mặc định","Bảng ARP như bảng định tuyến toàn cầu","Chỉ broadcast lớp 2","DNS cache như router"],"correct":0}]},{"course":64,"order":9,"questions":[{"text":"Trong TCP, ACK thường biểu thị gì?","options":["Yêu cầu DNS","Số lượng switch","Địa chỉ MAC","Xác nhận đã nhận dữ liệu"],"correct":3},{"text":"Điểm khác của UDP so với TCP là gì?","options":["Không bắt buộc tạo kết nối trước khi gửi datagram","Luôn có kiểm soát luồng chặt hơn TCP","Luôn đảm bảo thứ tự","Luôn truyền lại gói mất"],"correct":0},{"text":"Cổng 53 thường gắn với dịch vụ nào?","options":["SSH","DNS","HTTPS","SMTP"],"correct":1},{"text":"TCP cung cấp cơ chế nào mà UDP cơ bản không bảo đảm?","options":["Truyền tin đáng tin cậy có xác nhận và truyền lại","Không có tiêu đề","Không dùng cổng","Không truyền gói"],"correct":0},{"text":"UDP thường phù hợp với ứng dụng nào?","options":["Chỉ lưu file cục bộ","Truyền thời gian thực có thể chấp nhận mất gói","Giao dịch bắt buộc xác nhận từng byte theo TCP","Bắt buộc bảo đảm đúng thứ tự mọi gói"],"correct":1},{"text":"TCP thiết lập kết nối bằng thủ tục nào?","options":["DNS lookup duy nhất","SMTP login","Three-way handshake","One-way broadcast"],"correct":2},{"text":"Số cổng TCP/UDP dùng để xác định điều gì?","options":["Địa chỉ MAC duy nhất","Mã quốc gia của router","Số lượng RAM","Tiến trình hoặc dịch vụ đích trên host"],"correct":3},{"text":"TCP có cơ chế kiểm soát luồng phổ biến nào?","options":["Cửa sổ nhận","TTL tuyến","Bảng MAC","DHCP lease"],"correct":0},{"text":"UDP có thuộc tính nào?","options":["Bảo đảm thứ tự mọi datagram","Không hướng kết nối","Bắt buộc bắt tay ba bước","Tự động truyền lại mọi gói"],"correct":1},{"text":"TCP và UDP đều nằm ở tầng nào?","options":["Tầng vật lý","Tầng liên kết dữ liệu","Tầng vận chuyển","Tầng ứng dụng"],"correct":2}]},{"course":64,"order":10,"questions":[{"text":"Trình duyệt khi truy cập https:// thường dùng giao thức ứng dụng nào?","options":["SNMP","HTTP chạy qua TLS","FTP thuần túy","SMTP"],"correct":1},{"text":"Tên miền cần giải phân giải thành IP thông qua hệ thống nào?","options":["VLAN","STP","DNS","ARP chỉ trong LAN"],"correct":2},{"text":"Dịch vụ FTP truyền thống chủ yếu phục vụ chức năng nào?","options":["Định tuyến IP","Cấp DHCP","Đồng bộ thời gian NTP duy nhất","Truyền tập tin"],"correct":3},{"text":"DNS dùng để làm gì?","options":["Đổi màu website","Mã hóa ổ đĩa","Phân giải tên miền thành thông tin như địa chỉ IP","Cấp nguồn cho router"],"correct":2},{"text":"HTTP là giao thức phục vụ điều gì?","options":["Cấp phát IPv4 tự động","Định tuyến giữa các mạng","Gửi tín hiệu điện trên cáp đồng","Trao đổi tài nguyên web theo mô hình yêu cầu và phản hồi"],"correct":3},{"text":"HTTPS bổ sung cơ chế bảo vệ phổ biến nào so với HTTP thông thường?","options":["TLS mã hóa và xác thực kết nối","Chỉ rút ngắn URL","Loại bỏ IP","Bắt buộc dùng UDP"],"correct":0},{"text":"DHCP giúp máy trạm làm gì?","options":["Tạo tài khoản email","Nhận cấu hình mạng tự động","Duyệt trang web","Đổi hình nền"],"correct":1},{"text":"SMTP thường dùng để làm gì?","options":["Tải trang HTML từ server","Cấp IP cho máy","Gửi thư điện tử","Phân giải DNS"],"correct":2},{"text":"Máy chủ web thường tiếp nhận HTTP trên cổng mặc định nào?","options":["25","53","110","80"],"correct":3},{"text":"HTTPS thường sử dụng cổng TCP mặc định nào?","options":["443","21","22","67"],"correct":0}]},{"course":64,"order":11,"questions":[{"text":"Sơ đồ IP của mạng cần thể hiện điều gì?","options":["Chỉ màu máy in","Chỉ hãng của màn hình","Chỉ tên người dùng","Các subnet, gateway và thiết bị sử dụng"],"correct":3},{"text":"Để giảm sự cố, cần ghi lại cấu hình thiết bị mạng vì sao?","options":["Thuận tiện khôi phục và kiểm tra thay đổi","Để loại bỏ mọi mật khẩu","Để không cần sơ đồ","Để bỏ DHCP"],"correct":0},{"text":"Trước khi bàn giao mạng cần kiểm thử yếu tố nào?","options":["Chỉ phiên bản trình duyệt","Kết nối, DNS, Internet, phân quyền và dịch vụ","Chỉ màu vỏ router","Chỉ số lượng chuột"],"correct":1},{"text":"Bước đầu khi thiết kế mạng văn phòng nhỏ là gì?","options":["Xác định số người dùng, dịch vụ và yêu cầu kết nối","Mua thiết bị ngẫu nhiên","Cấm mọi cấu hình IP","Đổi tên máy tùy ý"],"correct":0},{"text":"Để phân tách phòng ban trong mạng switch, có thể dùng giải pháp nào?","options":["Tăng độ sáng màn hình","VLAN","Đổi màu cáp","Đặt tên file"],"correct":1},{"text":"Sau khi cấu hình IP, kiểm tra truy cập gateway bằng công cụ nào?","options":["taskkill","notepad","ping","format"],"correct":2},{"text":"Trong mạng nhỏ, DHCP server giúp gì?","options":["Lưu đáp án quiz","Thay thế switch vật lý","Mã hóa mọi cáp mạng","Cấp phát cấu hình IP tự động cho máy trạm"],"correct":3},{"text":"Quy tắc an toàn cơ bản cho thiết bị mạng là gì?","options":["Đổi mật khẩu mặc định và giới hạn quyền quản trị","Giữ nguyên mật khẩu mặc định","Mở mọi cổng quản trị ra Internet","Tắt toàn bộ nhật ký"],"correct":0},{"text":"Vì sao cần vẽ sơ đồ kết nối trước khi triển khai?","options":["Thay thế mọi cấu hình","Dễ kiểm tra vị trí thiết bị, địa chỉ và xử lý sự cố","Làm tăng tốc độ CPU","Bảo đảm không bao giờ mất điện"],"correct":1},{"text":"Khi một máy không truy cập Internet, bước kiểm tra hợp lý là gì?","options":["Đổi bàn phím","Tắt hệ thống mạng vĩnh viễn","Kiểm tra link, địa chỉ IP, gateway và DNS theo từng lớp","Xóa toàn bộ máy"],"correct":2}]}]$QUIZ_JSON$::jsonb)
  LOOP
    v_cid:=(spec->>'course')::int;
    v_ord:=(spec->>'order')::int;
    SELECT lesson_id INTO STRICT v_lesson FROM lms.lessons
      WHERE course_id=v_cid AND lesson_order=v_ord AND is_published AND NOT is_deleted;
    SELECT quiz_id INTO STRICT v_quiz FROM assessment.quizzes
      WHERE course_id=v_cid AND lesson_id=v_lesson AND is_published AND NOT is_deleted;
    SELECT COUNT(*) INTO v_count FROM assessment.questions WHERE quiz_id=v_quiz;
    IF v_count NOT IN (3,10) THEN
      RAISE EXCEPTION 'Quiz % has % questions; expected 3 or 10; not modified',v_quiz,v_count;
    END IF;
    IF v_count=3 THEN
      SELECT COUNT(*) INTO v_attempts FROM assessment.quiz_attempts WHERE quiz_id=v_quiz;
      -- Never change question/answer content after an attempt exists.
      IF v_attempts=0 THEN
        FOR v_k IN 1..3 LOOP
          pack:=spec->'questions'->(v_k-1);
          SELECT question_id INTO STRICT v_old_question FROM assessment.questions
            WHERE quiz_id=v_quiz AND question_order=v_k;
          IF (SELECT COUNT(*) FROM assessment.answers WHERE question_id=v_old_question)<>4 THEN
            RAISE EXCEPTION 'Question % does not have exactly 4 options; abort',v_old_question;
          END IF;
          UPDATE assessment.questions SET question_text=pack->>'text',question_type='SINGLE_CHOICE',points=1
            WHERE question_id=v_old_question;
          FOR v_j IN 1..4 LOOP
            SELECT answer_id INTO STRICT v_answer FROM assessment.answers
              WHERE question_id=v_old_question AND answer_order=v_j;
            UPDATE assessment.answers SET
              answer_text=pack->'options'->>(v_j-1),
              is_correct=((pack->>'correct')::int=v_j-1)
            WHERE answer_id=v_answer;
          END LOOP;
        END LOOP;
      ELSE
        RAISE NOTICE 'Quiz % has % historic attempts; preserving its 3 original questions',v_quiz,v_attempts;
      END IF;
      -- The remaining seven questions are unique and lesson-specific.
      FOR v_k IN 4..10 LOOP
        pack:=spec->'questions'->(v_k-1);
        INSERT INTO assessment.questions(quiz_id,question_text,question_type,question_order,points)
        VALUES(v_quiz,pack->>'text','SINGLE_CHOICE',v_k,1)
        RETURNING question_id INTO v_question;
        FOR v_j IN 1..4 LOOP
          INSERT INTO assessment.answers(question_id,answer_text,is_correct,answer_order)
          VALUES(v_question,pack->'options'->>(v_j-1),(pack->>'correct')::int=v_j-1,v_j);
        END LOOP;
      END LOOP;
    ELSE
      FOR v_k IN 4..10 LOOP
        pack:=spec->'questions'->(v_k-1);
        IF NOT EXISTS(SELECT 1 FROM assessment.questions
          WHERE quiz_id=v_quiz AND question_order=v_k AND question_text=pack->>'text') THEN
          RAISE EXCEPTION 'Quiz % question % conflicts with patch; abort',v_quiz,v_k;
        END IF;
      END LOOP;
    END IF;
    UPDATE assessment.quizzes
       SET time_limit_seconds=GREATEST(COALESCE(time_limit_seconds,0),900),updated_at=now()
       WHERE quiz_id=v_quiz;
  END LOOP;
  FOR v_pdf IN SELECT value FROM jsonb_array_elements($PDF_JSON$[{"course":63,"order":2,"file":"732c376f-9ed8-5e87-a3d5-93c58b530a03.pdf"},{"course":63,"order":3,"file":"0f13bf52-4698-5bd4-b144-701ce6d70df9.pdf"},{"course":63,"order":4,"file":"2198ebbc-b966-52b2-8976-ac01d9881fec.pdf"},{"course":63,"order":5,"file":"ce3ada21-0891-503b-b87b-144354a68d66.pdf"},{"course":63,"order":6,"file":"5268c6fe-0899-5d7e-b1fe-eb4edf8a03e3.pdf"},{"course":63,"order":7,"file":"deda9d61-a943-5b91-a85c-32d445a73a76.pdf"},{"course":63,"order":8,"file":"572ddaf9-2279-5ce9-9df4-53cfbf4bd8e8.pdf"},{"course":63,"order":9,"file":"604f4892-1978-5a3a-9593-854f1b75294c.pdf"},{"course":63,"order":10,"file":"9af8462b-62f8-5ee9-bb4d-93cda7a5c982.pdf"},{"course":63,"order":11,"file":"0c7f8bd9-26e8-59f1-b74b-c0e327528c0c.pdf"},{"course":63,"order":12,"file":"b4fc03d8-57cc-5346-84e9-8eb1b657d669.pdf"},{"course":63,"order":13,"file":"f7eee561-0963-5cad-ba8b-78b4386d99a0.pdf"},{"course":63,"order":14,"file":"ea0b1354-f302-5397-92e1-ada8d76e135e.pdf"},{"course":63,"order":15,"file":"19c09797-fb5c-5325-aa66-2a919660255c.pdf"}]$PDF_JSON$::jsonb)
  LOOP
    SELECT lesson_id INTO STRICT v_lesson FROM lms.lessons
      WHERE course_id=(v_pdf->>'course')::int AND lesson_order=(v_pdf->>'order')::int
      AND is_published AND NOT is_deleted;
    v_url:='vedu-file:'||(v_pdf->>'file');
    IF NOT EXISTS(SELECT 1 FROM lms.lesson_resources
      WHERE lesson_id=v_lesson AND resource_type='PDF' AND resource_url=v_url) THEN
      INSERT INTO lms.lesson_resources(lesson_id,resource_type,title,resource_url,display_order)
      VALUES(v_lesson,'PDF','Tài liệu PDF theo bài · VEDU',v_url,
       (SELECT COALESCE(MAX(display_order),0)+1 FROM lms.lesson_resources WHERE lesson_id=v_lesson));
    END IF;
  END LOOP;
END $vedu_patch$;
COMMIT;
